import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第五卷 答案 · 第100章 夜宵","description":"","frontmatter":{},"headers":[],"relativePath":"第100章_夜宵.md","filePath":"第100章_夜宵.md"}'),r={name:"第100章_夜宵.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第五卷-答案-·-第100章-夜宵" tabindex="-1">第五卷 答案 · 第100章 夜宵 <a class="header-anchor" href="#第五卷-答案-·-第100章-夜宵" aria-label="Permalink to &quot;第五卷 答案 · 第100章 夜宵&quot;">​</a></h1><p>周三晚上有雾。</p><p>我从图书馆侧门出来，雾已经漫到后街口。路灯泡在雾里，光晕散开，照不清路，只照得见人影一团团地晃。夜市的声音隔着雾传来，闷闷的，像隔了一层水。</p><p>南雾老乡小桌在老位置，塑料棚上凝着水珠，往下滴。周野先到了，占了里面的座，桌上扣着三个茶杯，壶嘴还冒着热气。</p><p>“温棠呢？”我问。</p><p>“盯炒面去了，说人多。”周野给我倒热水，“先暖暖手，你手指都凉了。”</p><p>我捧住杯子，热气熏着下巴。凳面带着凉意，透过裤子渗上来，后背很快也被雾打潮了。我站起来把棚边垂下来的一角塑料布系紧，水珠顺着指缝滑下去，凉得我缩了下手。风一吹，棚顶哗哗响，我伸手压住晃动的灯线，灯才稳下来，光重新聚在桌心。</p><p>温棠端着盘子回来，走得很快，嘴里吸着气：“烫烫烫，让让。”</p><p>炒面落在桌心，发出一声脆响。面条泛着油光，青菜卧在上面，胡萝卜丝切得极细，焦香混着酱油香，一下子扑到脸上。我闭了下眼，肩膀慢慢松了。</p><p>“糖水马上到。”温棠坐下，擦了擦额头的汗，“让阿姨多加了料。”</p><p>旁边铁板滋滋响，油点溅起又落下。有个小孩跑过，带起一阵风，雾被搅动一下，又合拢。</p><p>糖水来了，一碗清补凉，一碗绿豆沙。冰块浮着，轻轻相撞，碗壁很快凝了一层水珠，摸上去凉凉的，滑滑的。我去接那碗热的，指尖碰到碗沿，烫得换了只手，又赶紧垫上纸巾，才稳稳端回来。</p><p>周野舀了一大口，忽然冒出一句原声：“每周三晚，三个人，雾气，糖水，炒面，少一样都不算过完这周。”他说得一本正经，温棠笑他像报菜名，我也跟着笑，胸口那点闷被笑散了些。</p><p>我舀起一勺清补凉，椰奶香很浓，芋头煮透了，入口就化。冰凉从舌尖滑到喉咙，刚才被热气熏热的脸，一下子凉了下来。</p><p>温棠吃得很快，锅气很足，越嚼越香。她吃到一半停下来，把自己碗里的青菜拨给我，说你太瘦了，得吃点绿的。</p><p>雾浓了些，甜香油香全混在一起。远处有人喊收摊，铁皮桶磕碰响，雾里传得很近又很远。</p><p>周野看了我一眼，声音放轻：“你最近怎么样？”</p><p>“上课，看书，写东西。”我说。</p><p>“江苒呢？”</p><p>勺子停在半空，冰块化了一点，水面晃了晃，灯光碎在里面。</p><p>“分开了。”我说，“有一阵子了。”</p><p>桌上静了一下，只有铁板还在响。塑料棚上的水滴下来，正落在我手背，凉得我动了一下，又没擦。</p><p>“之前看你们挺好的。”温棠放下筷子，“她还把纸星星装满了一罐，说要许愿。”</p><p>“是装满了。”我说，“停电那晚，她抱着罐子说里面有光。磁带放完一面，咔哒停了，谁也没去翻面。”</p><p>“那随身听呢？”周野问。</p><p>“她还回来了，连盒子都擦干净了。”我说，“只有星星罐没还，说留个念想。”</p><p>我夹了一口面，烫意带着咸香，眼眶被热气熏得发热。我低头多吃了两口，把那点酸意压下去。</p><p>“我跟她讲过老街。”我说，“讲我算半留守，爸妈在外面，我一直跟奶奶住。她听得很认真，还问奶奶包的粽子是甜是咸。”</p><p>“她对你上心。”温棠说。</p><p>“上心。”我点头，“所以分开那天，她把平安结放在桌上，绳头理得很平。她说这东西贵重，她留不住，让我还给奶奶。”</p><p>我从口袋摸出那个结，放在桌上。红绳旧了，边角起毛，在灯下还是很红。桌面的水渍沾上去，洇开一小点深色。</p><p>三个人都看着它，谁也没先碰。雾气落在结上，红绳颜色深了一点，像被夜浸透了。</p><p>“没再争取？”温棠问。</p><p>“把小说压下了。”我说，“本来写了很久，想送给她看。结果她阿婆病倒，我天天往老街跑。走廊里全是药水味，监护仪一夜没停。那种时候，心是乱的，送出去会伤人，就暂缓了。”</p><p>周野叹气：“奶奶现在呢？”</p><p>“稳住了，就是瘦了。”我说，“我给她削苹果，她笑我手艺不行，说皮削得比雾还薄，尽浪费。”</p><p>温棠碰了碰我的杯子：“你也难，两头牵挂。”</p><p>“习惯了。”我说，“从小跟奶奶住，她去哪儿都带着我。我坐石阶看雾从水面升起来，她把衣服搭上竹竿，水珠落在青苔上。”</p><p>“街坊也好，谁家做了好吃的，都端一碗来。晚上她给我留灯。”我说。灯这个字一出口，我喉咙紧了一下，又喝了口热水压住。</p><p>周野点头：“你是闷，有事自己扛。”</p><p>“想改。”我说，“可话到嘴边，总觉得矫情。”</p><p>糖水的冰化完了，甜味淡了。我捧着碗，凉意渗进掌心，又暖回来一点。</p><p>“记得第一次来这儿，也是大雾。”温棠笑，“三个人拼一桌，就因为口音一样。”</p><p>“那天你抢我青菜。”周野说。</p><p>“你青菜多。”</p><p>三个碗碰在一起，清脆一响，水珠溅到桌上，很快又凝住。</p><p>“再坐会儿。”我说，“雾还没散。”</p><p>谁也没起身，像怕一动，热气就散了。棚外雾走得慢，灯晕始终罩着这张小桌，像单独留的一盏。</p><p>散场时温棠先走了一步。空椅背上，还搭着她落下的一把伞，伞骨微弯，伞柄上系着一截红绳。</p><p>周野把伞摘下来递给我：“走得急，伞都忘了。”</p><p>伞下压着一张小纸条，是宋阿婆托她带来的一句口信：雾大路滑，人顾好，东西不急，伞先借你们挡一挡。</p>',51)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
